-- ASCEND ATHLETICS: schema. No operational or financial seed data.
create extension if not exists pgcrypto with schema extensions;
create table public.profiles(id uuid primary key references auth.users(id) on delete restrict,full_name text not null default '',phone text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.staff_roles(user_id uuid primary key references profiles(id),role text not null check(role in ('owner','assistant')),permissions jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.customers(id uuid primary key default gen_random_uuid(),profile_id uuid unique references profiles(id),name text not null check(length(trim(name))>0),email text,phone text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index customers_email_idx on customers(lower(email));
create table public.customer_addresses(id uuid primary key default gen_random_uuid(),customer_id uuid not null references customers(id),recipient_name text not null,phone text not null,state text not null,city text not null,area text not null,address text not null,landmark text,created_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,sort_order integer not null default 0,active boolean not null default true);
create table public.products(id uuid primary key default gen_random_uuid(),category_id uuid references categories(id),name text not null,slug text not null unique,description text not null default '',price numeric(14,2) not null check(price>0),cost_price numeric(14,2) check(cost_price>=0),status text not null default 'draft' check(status in ('draft','coming_soon','active','unavailable')),featured boolean not null default false,size_guide text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.product_variants(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id),sku text not null unique,size text not null default 'One Size',color text not null default 'Default',stock_on_hand integer not null default 0 check(stock_on_hand>=0),stock_reserved integer not null default 0 check(stock_reserved>=0 and stock_reserved<=stock_on_hand),stock_sold integer not null default 0 check(stock_sold>=0),stock_available integer generated always as(stock_on_hand-stock_reserved) stored,stock_confirmed_at timestamptz,low_stock_threshold integer not null default 5 check(low_stock_threshold>=0),created_at timestamptz not null default now(),unique(product_id,size,color));
create index product_variants_product_idx on product_variants(product_id);
create table public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id),storage_path text not null,alt text not null default '',sort_order integer not null default 0);
create table public.collections(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text not null default '',banner_path text,status text not null default 'draft' check(status in ('draft','published','upcoming')),launch_at timestamptz,created_at timestamptz not null default now());
create table public.collection_products(collection_id uuid references collections(id),product_id uuid references products(id),primary key(collection_id,product_id));
create table public.business_settings(id integer primary key default 1 check(id=1),bank_name text,bank_account_number text,bank_account_holder text,payment_instructions text,pickup_location text,pickup_instructions text,pickup_contact text,pickup_hours text,contact_email text,whatsapp_number text,instagram_url text,timezone text not null default 'Africa/Lagos',reservation_minutes integer not null default 60 check(reservation_minutes between 5 and 10080),reminders_enabled boolean not null default false,reminder_days jsonb not null default '[7,2,0]',updated_at timestamptz not null default now());
create table public.delivery_rates(id uuid primary key default gen_random_uuid(),state text not null,city text,area text,fee numeric(14,2) not null check(fee>=0),active boolean not null default true,created_at timestamptz not null default now());
create unique index delivery_rates_location_idx on delivery_rates(lower(state),coalesce(lower(city),''),coalesce(lower(area),''));
create table public.orders(id uuid primary key default gen_random_uuid(),order_number text not null unique default('ASC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))),customer_id uuid not null references customers(id),source text not null default 'website' check(source in ('website','whatsapp','instagram','in_person','other')),customer_name text not null,customer_email text,customer_phone text not null,fulfillment_method text not null check(fulfillment_method in ('pickup','delivery')),delivery_details jsonb not null default '{}',delivery_status text not null check(delivery_status in ('pending','quoted','approved')),delivery_fee numeric(14,2) check(delivery_fee>=0),subtotal numeric(14,2) not null check(subtotal>=0),total_amount numeric(14,2) check(total_amount>=0),fulfillment_status text not null default 'pending' check(fulfillment_status in ('pending','processing','ready_for_pickup','shipped','delivered','picked_up','cancelled')),resolution_required boolean not null default false,pay_later_authorized boolean not null default false,guest_token_hash text not null unique,reservation_expires_at timestamptz not null,courier_name text,tracking_reference text,created_by uuid references profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index orders_customer_idx on orders(customer_id,created_at desc);
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id),variant_id uuid not null references product_variants(id),product_name text not null,sku text not null,size text not null,color text not null,quantity integer not null check(quantity between 1 and 1000),unit_price numeric(14,2) not null check(unit_price>0),unit_cost numeric(14,2) check(unit_cost>=0),unique(order_id,variant_id));
create table public.stock_reservations(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id),variant_id uuid not null references product_variants(id),quantity integer not null check(quantity>0),status text not null default 'active' check(status in ('active','consumed','released','expired')),expires_at timestamptz not null,created_at timestamptz not null default now(),unique(order_id,variant_id));
create index stock_reservations_expiry_idx on stock_reservations(expires_at) where status='active';
create table public.stock_movements(id uuid primary key default gen_random_uuid(),variant_id uuid not null references product_variants(id),order_id uuid references orders(id),kind text not null,quantity_delta integer not null default 0,reserved_delta integer not null default 0,actor_id uuid references profiles(id),note text,created_at timestamptz not null default now());
create table public.order_notes(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id),body text not null,created_by uuid references profiles(id),created_at timestamptz not null default now());
create table public.fulfillment_events(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id),status text not null,actor_id uuid references profiles(id),created_at timestamptz not null default now());
create table public.coaching_packages(id uuid primary key default gen_random_uuid(),name text not null,mode text not null check(mode in ('physical','online')),description text not null default '',price numeric(14,2) not null check(price>0),billing_model text not null default 'monthly' check(billing_model in ('monthly','per_session','session_bundle','fixed_duration')),duration_months integer not null default 1 check(duration_months between 1 and 36),duration_days integer check(duration_days between 1 and 3650),session_count integer check(session_count between 1 and 1000),features jsonb not null default '[]',active boolean not null default false,created_at timestamptz not null default now(),check(billing_model!='fixed_duration' or duration_days is not null),check(billing_model not in ('per_session','session_bundle') or session_count is not null));
create table public.coaching_enrollments(id uuid primary key default gen_random_uuid(),customer_id uuid not null references customers(id),package_id uuid not null references coaching_packages(id),package_name text not null,mode text not null check(mode in ('physical','online')),billing_model text not null,price numeric(14,2) not null check(price>0),duration_months integer not null,duration_days integer,session_count integer,status text not null default 'requested' check(status in ('requested','active','expired','cancelled')),start_date date,expiry_date date,sessions_used integer not null default 0 check(sessions_used>=0),training_preferences jsonb not null default '{}',pay_later_authorized boolean not null default false,activated_by uuid references profiles(id),created_at timestamptz not null default now(),check(expiry_date is null or start_date is not null and expiry_date>start_date),check(session_count is null or sessions_used<=session_count));
create index coaching_enrollment_customer_idx on coaching_enrollments(customer_id);
create index coaching_expiry_idx on coaching_enrollments(expiry_date) where status='active';
create table public.coaching_session_usage(id uuid primary key default gen_random_uuid(),enrollment_id uuid not null references coaching_enrollments(id),session_date date not null,note text,created_by uuid references profiles(id),created_at timestamptz not null default now());
create table public.invoices(id uuid primary key default gen_random_uuid(),customer_id uuid not null references customers(id),order_id uuid unique references orders(id),enrollment_id uuid unique references coaching_enrollments(id),total_amount numeric(14,2) check(total_amount>=0),amount_paid numeric(14,2) not null default 0 check(amount_paid>=0),amount_refunded numeric(14,2) not null default 0 check(amount_refunded>=0 and amount_refunded<=amount_paid),outstanding_amount numeric(14,2) generated always as(greatest(total_amount-amount_paid,0)) stored,payment_status text not null default 'pending' check(payment_status in ('pending','evidence_submitted','partially_paid','paid','rejected','refunded')),created_at timestamptz not null default now(),check((order_id is null)!=(enrollment_id is null)));
create index invoices_customer_idx on invoices(customer_id);
create table public.payments(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references invoices(id),submitted_amount numeric(14,2) not null check(submitted_amount>0),amount_received numeric(14,2) not null default 0 check(amount_received>=0),transfer_reference text not null,bank_name text,transferred_at timestamptz,status text not null default 'evidence_submitted' check(status in ('pending','evidence_submitted','verified','rejected')),bank_credit_reference text unique,verified_by uuid references profiles(id),verified_at timestamptz,notes text,created_by uuid references profiles(id),created_at timestamptz not null default now(),check(status!='verified' or amount_received>0 and bank_credit_reference is not null and verified_by is not null and verified_at is not null));
create index payments_invoice_idx on payments(invoice_id);
create unique index payments_claim_dedup_idx on payments(invoice_id,lower(transfer_reference)) where status!='rejected';
create table public.payment_evidence(id uuid primary key default gen_random_uuid(),payment_id uuid not null references payments(id),storage_path text not null unique,created_at timestamptz not null default now());
create table public.refunds(id uuid primary key default gen_random_uuid(),payment_id uuid not null references payments(id),amount numeric(14,2) not null check(amount>0),reason text not null,external_reference text not null unique,created_by uuid not null references profiles(id),created_at timestamptz not null default now());
create table public.financial_adjustments(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references invoices(id),payment_id uuid references payments(id),kind text not null check(kind in ('receipt','refund','pay_later_authorized','delivery_quote')),amount numeric(14,2) not null,actor_id uuid references profiles(id),note text,created_at timestamptz not null default now());
create table public.expenses(id uuid primary key default gen_random_uuid(),category text not null,description text not null,amount numeric(14,2) not null check(amount>0),spent_on date not null,created_by uuid not null references profiles(id),created_at timestamptz not null default now());
create table public.newsletter_subscribers(id uuid primary key default gen_random_uuid(),email text not null unique,name text,status text not null default 'subscribed' check(status in ('subscribed','unsubscribed')),unsubscribe_token_hash text not null unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.marketing_consents(id uuid primary key default gen_random_uuid(),subscriber_id uuid not null references newsletter_subscribers(id),action text not null check(action in ('opt_in','opt_out')),source text not null,policy_version text not null,created_at timestamptz not null default now());
create table public.campaigns(id uuid primary key default gen_random_uuid(),name text not null,subject text not null,body_html text not null,status text not null default 'draft' check(status in ('draft','approved','sending','sent')),approved_by uuid references profiles(id),approved_at timestamptz,created_by uuid references profiles(id),created_at timestamptz not null default now(),check(status='draft' or approved_by is not null and approved_at is not null));
create table public.campaign_recipients(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns(id),subscriber_id uuid not null references newsletter_subscribers(id),status text not null default 'pending' check(status in ('pending','sending','sent','failed','skipped')),provider_message_id text,last_error text,sent_at timestamptz,unique(campaign_id,subscriber_id));
create table public.notifications(id uuid primary key default gen_random_uuid(),enrollment_id uuid references coaching_enrollments(id),customer_id uuid references customers(id),kind text not null,scheduled_for timestamptz not null,dedup_key text not null unique,status text not null default 'pending' check(status in ('pending','sending','sent','failed')),provider_message_id text,last_error text,sent_at timestamptz,created_at timestamptz not null default now());
create table public.site_content(id uuid primary key default gen_random_uuid(),section text not null unique,title text,body text,image_path text,data jsonb not null default '{}',published boolean not null default false,updated_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references profiles(id),action text not null,table_name text not null,record_id text,before_data jsonb,after_data jsonb,created_at timestamptz not null default now());
create table public.rate_limits(key text primary key,window_start timestamptz not null,hits integer not null check(hits>=0));
